import{_ as t,o as s,c as a,a4 as i}from"./chunks/framework.BE47AOxC.js";const h=JSON.parse('{"title":"Contribuer à Teuthis-CMS","description":"Extrait de CONTRIBUTING.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"Contribuer à Teuthis-CMS","description":"Extrait de CONTRIBUTING.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/contribuer.md","filePath":"developpeurs/contribuer.md"}'),o={name:"developpeurs/contribuer.md"};function d(n,e,r,l,c,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="contribuer-à-teuthis-cms" tabindex="-1">Contribuer à Teuthis-CMS <a class="header-anchor" href="#contribuer-à-teuthis-cms" aria-label="Permalink to &quot;Contribuer à Teuthis-CMS {#contribuer-à-teuthis-cms}&quot;">​</a></h1><p>Ce document fixe la façon de nommer les commits et de suivre le travail sur GitHub. Il applique au dépôt la convention Git du Product Owner (<a href="https://gist.github.com/Bastien-OC20/4efce597878056b5239a527f4e5e51a5" target="_blank" rel="noreferrer">gist <code>0_Git_Convention.md</code></a>), adaptée sur deux points : les messages sont <strong>en français</strong>, et tout se pousse <strong>sur <code>main</code></strong>, sans branche ni pull request.</p><p>Les règles de travail propres au code (langue, fins de ligne, vérifications à lancer comme la CI) sont dans <code>CLAUDE.md</code>.</p><h2 id="1-un-lot-de-travail--une-issue" tabindex="-1">1. Un lot de travail = une issue <a class="header-anchor" href="#1-un-lot-de-travail--une-issue" aria-label="Permalink to &quot;1. Un lot de travail = une issue {#1-un-lot-de-travail--une-issue}&quot;">​</a></h2><p>Chaque lot de travail a son issue GitHub, ouverte <strong>avant</strong> le premier commit avec le modèle « Lot de travail ». Elle dit ce qui est livré, les ADR concernées, et ce qui reste hors du lot.</p><p>Un défaut constaté (recette, CI, exploitation) a son issue, ouverte avec le modèle « Défaut ».</p><p>Le numéro de l&#39;issue se cite dans le pied du commit (§ 2.4). Pas de branche par ticket : le Product Owner commite et pousse lui-même sur <code>main</code>.</p><h2 id="2-messages-de-commit" tabindex="-1">2. Messages de commit <a class="header-anchor" href="#2-messages-de-commit" aria-label="Permalink to &quot;2. Messages de commit {#2-messages-de-commit}&quot;">​</a></h2><h3 id="21-forme" tabindex="-1">2.1 Forme <a class="header-anchor" href="#21-forme" aria-label="Permalink to &quot;2.1 Forme {#21-forme}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;(&lt;portée&gt;): &lt;titre&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;corps&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;pied&gt;</span></span></code></pre></div><p>Exemple :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span>feat(pages): ajoute le brouillon de page</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Les pages suivent le workflow éditorial des contenus : brouillon,</span></span>
<span class="line"><span>relecture, approuvée, publiée, avec un journal. Une page non publiée,</span></span>
<span class="line"><span>ou placée sous un parent non publié, est invisible du public partout.</span></span>
<span class="line"><span>Migration 0049 : les pages existantes deviennent publiées.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Closes #12</span></span></code></pre></div><h3 id="22-type" tabindex="-1">2.2 Type <a class="header-anchor" href="#22-type" aria-label="Permalink to &quot;2.2 Type {#22-type}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Quand</th></tr></thead><tbody><tr><td><code>feat</code></td><td>Une fonctionnalité nouvelle pour un utilisateur, un exploitant ou un front.</td></tr><tr><td><code>fix</code></td><td>La correction d&#39;un défaut.</td></tr><tr><td><code>docs</code></td><td>Documentation seule : ADR, notice, README, CONTRIBUTING.</td></tr><tr><td><code>refactor</code></td><td>Une restructuration du code, sans changement de comportement.</td></tr><tr><td><code>perf</code></td><td>Une amélioration de performance mesurée.</td></tr><tr><td><code>test</code></td><td>Des tests seuls, sans changement du code testé.</td></tr><tr><td><code>build</code></td><td>Dépendances, images, empaquetage.</td></tr><tr><td><code>ci</code></td><td>Workflows et scripts de la CI ou de la publication.</td></tr><tr><td><code>chore</code></td><td>Entretien sans effet sur le produit : passage de version, nettoyage.</td></tr><tr><td><code>style</code></td><td>Mise en forme seule (espaces, ordre des imports).</td></tr><tr><td><code>revert</code></td><td>L&#39;annulation d&#39;un commit précédent.</td></tr></tbody></table><h3 id="23-portée-et-titre" tabindex="-1">2.3 Portée et titre <a class="header-anchor" href="#23-portée-et-titre" aria-label="Permalink to &quot;2.3 Portée et titre {#23-portée-et-titre}&quot;">​</a></h3><ul><li><strong>Portée</strong> : la partie touchée, en minuscules, avec des tirets : <code>api</code>, <code>admin</code>, <code>front</code>, <code>pages</code>, <code>mediatheque</code>, <code>ia</code>, <code>rgpd</code>, <code>securite</code>, <code>exploitation</code>, <code>installateur</code>, <code>ci</code>, <code>adr</code>… Plusieurs portées se séparent par une virgule sans espace : <code>fix(securite,rgpd): …</code>. Une portée trop large (« divers ») ne dit rien : préférez plusieurs commits.</li><li><strong>Titre</strong> : il complète la phrase « Appliqué, ce commit… ». Un verbe d&#39;action, <strong>en minuscules, au présent</strong>, sans point final, <strong>72 caractères au plus</strong> pour tout le titre, type et portée compris.</li></ul><table tabindex="0"><thead><tr><th>Bon</th><th>Mauvais</th></tr></thead><tbody><tr><td><code>fix(installateur): préremplit le domaine du site public</code></td><td><code>fix: corrections diverses</code></td></tr><tr><td><code>feat(mediatheque): ajoute la date du document à l&#39;index</code></td><td><code>feat(mediatheque): Date des documents.</code></td></tr><tr><td><code>chore(version): passe en 0.3.1</code></td><td><code>nouvelle version</code></td></tr><tr><td><code>refactor(page-builder): extrait la validation des clés inconnues</code></td><td><code>refactor: amélioration du code et des tests et de la doc</code></td></tr></tbody></table><p>Verbes courants : <em>ajoute</em>, <em>retire</em>, <em>corrige</em>, <em>remplace</em>, <em>déplace</em>, <em>renomme</em>, <em>documente</em>, <em>optimise</em>, <em>met à jour</em>, <em>passe en</em> (version).</p><h3 id="24-corps-et-pied" tabindex="-1">2.4 Corps et pied <a class="header-anchor" href="#24-corps-et-pied" aria-label="Permalink to &quot;2.4 Corps et pied {#24-corps-et-pied}&quot;">​</a></h3><ul><li><strong>Corps</strong> (facultatif pour un changement évident) : <strong>pourquoi</strong> le changement, et ce qu&#39;un relecteur doit savoir (migration, changement de comportement visible, ADR concernée). Lignes de 72 caractères au plus. Ce que fait le code se lit dans le diff ; le corps dit ce que le diff ne dit pas.</li><li><strong>Pied</strong> : le lien avec l&#39;issue. <ul><li><code>Closes #N</code> : le commit termine l&#39;issue, GitHub la ferme.</li><li><code>Start #N</code> ou <code>Refs #N</code> : le commit fait avancer l&#39;issue sans la terminer.</li><li><code>BREAKING CHANGE: …</code> : un changement incompatible pour un front ou un exploitant (par exemple une route qui change de code de réponse).</li></ul></li></ul><h3 id="25-commande" tabindex="-1">2.5 Commande <a class="header-anchor" href="#25-commande" aria-label="Permalink to &quot;2.5 Commande {#25-commande}&quot;">​</a></h3><p>Le Product Owner commite et pousse sur <code>main</code>, en une ligne. Chaque <code>-m</code> ajoute un paragraphe : le titre, puis le corps, puis le pied.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">git</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> add</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> .</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;"> &amp;&amp; </span><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">git</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> commit</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -m</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> &quot;feat(pages): ajoute le brouillon de page&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -m</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> &quot;Les pages suivent le workflow éditorial des contenus. Migration 0049.&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -m</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> &quot;Closes #12&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;"> &amp;&amp; </span><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">git</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> push</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> origin</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> main</span></span></code></pre></div><p>Un modèle de message est fourni : <code>git config commit.template .gitmessage</code>, puis <code>git commit</code> sans <code>-m</code> ouvre l&#39;éditeur sur ce modèle.</p><h2 id="3-libellés" tabindex="-1">3. Libellés <a class="header-anchor" href="#3-libellés" aria-label="Permalink to &quot;3. Libellés {#3-libellés}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Libellé</th><th>Usage</th></tr></thead><tbody><tr><td><code>lot</code></td><td>Une issue de lot de travail.</td></tr><tr><td><code>bug</code></td><td>Un défaut.</td></tr><tr><td><code>adr</code></td><td>Le lot clôt ou modifie une action d&#39;ADR.</td></tr><tr><td><code>api</code>, <code>admin</code>, <code>front</code>, <code>exploitation</code>, <code>ci</code></td><td>La partie du dépôt touchée.</td></tr><tr><td><code>securite</code>, <code>rgpd</code>, <code>accessibility</code></td><td>Une exigence transverse.</td></tr><tr><td><code>recette</code></td><td>Un essai en conditions réelles (serveur jetable, vrai service).</td></tr><tr><td><code>release</code></td><td>La publication d&#39;une version.</td></tr></tbody></table>`,26)])])}const m=t(o,[["render",d]]);export{h as __pageData,m as default};
